const body = $input.first().json.body || $input.first().json;

const errors = [];

if (!body.tenant_id) errors.push('tenant_id is required');
if (!body.source_type) errors.push('source_type is required');
if (body.source_type && !['AI','HUMAN','SYSTEM'].includes(body.source_type)) {
  errors.push('source_type must be AI, HUMAN, or SYSTEM');
}
if (body.amount !== undefined && isNaN(Number(body.amount))) {
  errors.push('amount must be a number');
}

return [{
  json: {
    ...body,
    _validation: {
      isValid: errors.length === 0,
      errors,
      validatedAt: new Date().toISOString()
    }
  }
}];

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const body = $input.first().json;
const actionRequestId = uuidv4();
const decisionId = uuidv4();
const now = new Date().toISOString();

const insertPayload = {
  id: actionRequestId,
  tenant_id: body.tenant_id,
  source_type: body.source_type || 'AI',
  customer_id: body.customer_id || null,
  customer_name: body.customer_name || null,
  amount: body.amount ? Number(body.amount) : null,
  aging_bucket: body.aging_bucket || null,
  risk_level: body.risk_level || null,
  policy_context: body.policy_context || {},
  status: 'PENDING',
  evidence: { source: 'webhook', receivedAt: now }
};

return [{
  json: {
    ...body,
    action_request_id: actionRequestId,
    decision_id: decisionId,
    insert_payload: insertPayload,
    prepared_at: now
  }
}];

const aiResponse = $input.first().json;
const context = $('Generate action_request_id').first().json;

let recommendedAction = 'ESCALATE_MANAGER';
let aiReason = 'AI recommendation unavailable';
let confidence = 0.5;

try {
  const content = aiResponse.choices[0].message.content;
  const parsed = JSON.parse(content);
  recommendedAction = parsed.recommended_action || recommendedAction;
  aiReason = parsed.reason || aiReason;
  confidence = typeof parsed.confidence === 'number' ? parsed.confidence : confidence;
} catch(e) {
  aiReason = 'Parse error: ' + String(e.message).substring(0, 100);
}

return [{
  json: {
    ...context,
    recommended_action: recommendedAction,
    ai_reason: aiReason,
    ai_confidence: confidence
  }
}];

const data = $input.first().json;

const amount = Number(data.amount) || 0;
const riskLevel = (data.risk_level || '').toUpperCase();
const agingBucket = (data.aging_bucket || '').trim();
const customerId = data.customer_id;
const customerName = data.customer_name;
const policyContext = data.policy_context || {};
const legalReady = policyContext.legal_ready !== undefined
  ? Boolean(policyContext.legal_ready)
  : false;

let verdict = 'ALERT';
let policyRule = 'DEFAULT_ALERT';
let policyNotes = [];

// Rule 1: Missing customer identification
if (!customerId || !customerName) {
  verdict = 'FIX';
  policyRule = 'MISSING_CUSTOMER_DATA';
  policyNotes.push('customer_id or customer_name missing — required for collections action');
}
// Rule 2: Aged +180 AND not legal ready
else if (agingBucket === '+180' && !legalReady) {
  verdict = 'KILL';
  policyRule = 'LEGAL_NOT_READY_AGED_180';
  policyNotes.push('Debt aged +180 days and legal_ready is false — blocked by KFSA policy');
}
// Rule 3: High value + HIGH risk
else if (amount > 500000 && riskLevel === 'HIGH') {
  verdict = 'ALERT';
  policyRule = 'HIGH_VALUE_HIGH_RISK';
  policyNotes.push('Amount exceeds SAR 500,000 with HIGH risk — requires senior review');
}
// Rule 4: Low/medium risk within threshold
else if (amount <= 500000 && ['LOW', 'MEDIUM'].includes(riskLevel)) {
  verdict = 'SCALE';
  policyRule = 'WITHIN_AUTO_THRESHOLD';
  policyNotes.push('Risk and amount within automated processing limits');
}
// Default fallback
else {
  verdict = 'ALERT';
  policyRule = 'DEFAULT_ALERT';
  policyNotes.push('No specific rule matched — defaulting to escalation');
}

const decisionCode = 'KFSA-MOCK-' + Date.now();

return [{
  json: {
    ...data,
    verdict,
    policy_rule: policyRule,
    policy_notes: policyNotes,
    decision_code: decisionCode,
    evaluated_at: new Date().toISOString()
  }
}];

const data = $input.first().json;

const verdictStatusMap = {
  SCALE: 'APPROVED',
  FIX:   'NEEDS_FIX',
  ALERT: 'ESCALATED',
  KILL:  'BLOCKED'
};

const status = verdictStatusMap[data.verdict] || 'ESCALATED';
const executionAllowed = status === 'APPROVED';

return [{
  json: {
    ...data,
    status,
    execution_allowed: executionAllowed,
    decision_required: true
  }
}];

const ctx = $('Map Verdict to Status').first().json;

return [{
  json: {
    action_request_id: ctx.action_request_id,
    recommended_action: ctx.recommended_action,
    verdict: ctx.verdict,
    status: ctx.status,
    decision_required: true,
    decision_code: ctx.decision_code,
    execution_allowed: ctx.execution_allowed,
    evidence_logged: true,
    ai_reason: ctx.ai_reason,
    timestamp: new Date().toISOString()
  }
}];
